arguments.content:
import csv
import json
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo

DATASET = "/app/dataset"

def read_text(path):
    with open(path, "rb") as fh:
        data = fh.read()
    if data.startswith(b"\xff\xfe") or data.startswith(b"\xfe\xff"):
        return data.decode("utf-16")
    return data.decode("utf-8")


def norm_name(s):
    return " ".join(s.strip().split()).lower()


def load_farm_tz():
    text = read_text(f"{DATASET}/farms.csv")
    lines = text.splitlines()
    reader = csv.DictReader(lines)
    name_to_tz = {}
    for row in reader:
        name_to_tz[norm_name(row["farm_name"])] = row["timezone"]
    return name_to_tz


def load_registry():
    text = read_text(f"{DATASET}/farm_registry.csv")
    lines = text.splitlines()
    reader = csv.DictReader(lines)
    name_to_id = {}
    for row in reader:
        name_to_id[norm_name(row["farm_name"])] = row["farm_id"]
    return name_to_id


def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def parse_num(s):
    if s is None:
        return None
    s = s.strip()
    if s == "":
        return None
    if "," in s:
        s2 = s.replace(".", "").replace(",", ".")
    else:
        s2 = s
    try:
        return float(s2)
    except ValueError:
        return None


def parse_timestamp(s):
    s = s.strip()
    if s == "":
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None


name_to_tz = load_farm_tz()
name_to_id = load_registry()
calib = load_calibration()

id_to_tz = {}
for name, fid in name_to_id.items():
    id_to_tz[fid] = name_to_tz[name]

for letter in [chr(65 + i) for i in range(24)]:
    fid = f"FARM_{letter}"
    path = f"{DATASET}/production_FARM_{letter}.csv"
    text = read_text(path)
    lines = text.splitlines()
    header_line = lines[3]
    delim = ";" if ";" in header_line else ","
    header = [h.strip() for h in next(csv.reader([header_line], delimiter=delim))]
    data_lines = lines[4:]

    info = calib[fid]
    value_col = info["calibration_data"]["value_column_name"]
    offset = info["calibration_data"]["calibration_offset"]
    reading_type = info["sensor_info"]["reading_type"]
    unit = info["sensor_info"]["unit"]

    # find exact column (unstripped) matching value_col
    raw_header = next(csv.reader([header_line], delimiter=delim))
    try:
        value_idx = raw_header.index(value_col)
