import csv
import json
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo

DATASET = "/app/dataset"

DAY_START_UTC = datetime(2024, 3, 15, 0, 0, 0, tzinfo=timezone.utc)
DAY_END_UTC = datetime(2024, 3, 16, 0, 0, 0, tzinfo=timezone.utc)

SPIKE_THRESHOLD_C = 85.0
SPIKE_INVALIDATION = timedelta(minutes=45)

UNIT_TO_KWH = {
    "kwh": 1.0,
    "mwh": 1000.0,
    "wh": 0.001,
    "btu": 0.00029307107,
}

FARM_LETTERS = [chr(ord("A") + i) for i in range(24)]


def read_text(path):
    with open(path, "rb") as fh:
        data = fh.read()
    if data.startswith(b"\xff\xfe") or data.startswith(b"\xfe\xff"):
        return data.decode("utf-16")
    return data.decode("utf-8")


def norm_name(s):
    return " ".join(s.strip().split()).lower()


def load_farm_timezones():
    text = read_text(f"{DATASET}/farms.csv")
    reader = csv.DictReader(text.splitlines())
    return {norm_name(row["farm_name"]): row["timezone"] for row in reader}


def load_registry():
    text = read_text(f"{DATASET}/farm_registry.csv")
    reader = csv.DictReader(text.splitlines())
    return {norm_name(row["farm_name"]): row["farm_id"] for row in reader}


def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def parse_num(s):
    if s is None:
        return None
    s = s.strip()
    if s == "":
        return None
    if "," in s:
        s2 = s.replace(".", "").replace(",", ".")
    else:
        s2 = s
    try:
        return float(s2)
    except ValueError:
        return None


def parse_timestamp(s):
    s = s.strip()
    if s == "":
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None


def maintenance_windows_utc(id_to_tz):
    # Derived from /app/dataset/maintenance_notes.txt. Only COMPLETED windows
    # exclude readings; the CANCELLED panel inspection at Sakura Energy Site
    # (FARM_C, March 15th 09:00-11:00 local) is intentionally NOT included.
    windows = {}

    def add(fid, start_local, end_local):
        tz = ZoneInfo(id_to_tz[fid])
        start_utc = start_local.replace(tzinfo=tz).astimezone(timezone.utc)
        end_utc = end_local.replace(tzinfo=tz).astimezone(timezone.utc)
        windows.setdefault(fid, []).append((start_utc, end_utc))

    # Sakura Energy Site firmware update: 16 Mar 08:00-12:00 local, COMPLETED.
    add("FARM_C", datetime(2024, 3, 16, 8, 0, 0), datetime(2024, 3, 16, 12, 0, 0))
    # Vistula Photovoltaics scheduled cleaning: 15 Mar 12:00-14:00 local, COMPLETED.
    add("FARM_F", datetime(2024, 3, 15, 12, 0, 0), datetime(2024, 3, 15, 14, 0, 0))

    return windows


def process_farm(letter, fid, tz_name, calib_info, maint_windows):
    path = f"{DATASET}/production_FARM_{letter}.csv"
    text = read_text(path)
    lines = text.splitlines()
    header_line = lines[3]
    delim = ";" if ";" in header_line else ","
    raw_header = next(csv.reader([header_line], delimiter=delim))
    data_lines = lines[4:]

    value_col = calib_info["calibration_data"]["value_column_name"]
    offset = calib_info["calibration_data"]["calibration_offset"]
    reading_type = calib_info["sensor_info"]["reading_type"]
    unit = calib_info["sensor_info"]["unit"].strip().lower()

    value_idx = raw_header.index(value_col)
    temp_idx = [h.strip() for h in raw_header].index("inverter_temperature_C")

    raw_rows = [next(csv.reader([l], delimiter=delim)) for l in data_lines]

    # Duplicates handled via pandas drop_duplicates() semantics (exact duplicate rows).
    try:
        import pandas as pd

        df = pd.DataFrame(raw_rows)
        df = df.drop_duplicates()
        raw_rows = df.values.tolist()
    except ImportError:
        seen = set()
        deduped = []
        for r in raw_rows:
            t = tuple(r)
            if t in seen:
                continue
            seen.add(t)
            deduped.append(r)
        raw_rows = deduped

    tz = ZoneInfo(tz_name)
    parsed = []
    for r in raw_rows:
        ts = parse_timestamp(r[0])
        if ts is None:
            continue
        val = parse_num(r[value_idx])
        temp = parse_num(r[temp_idx])
        utc_ts = ts.replace(tzinfo=tz).astimezone(timezone.utc)
        parsed.append([utc_ts, val, temp])

    parsed.sort(key=lambda x: x[0])

    spike_windows = []
    for row in parsed:
        utc_ts, val, temp = row
        if temp is not None and temp > SPIKE_THRESHOLD_C:
            spike_windows.append((utc_ts, utc_ts + SPIKE_INVALIDATION))

    def in_spike_window(ts):
        for start, end in spike_windows:
            if start < ts <= end:
                return True
        return False

    windows = maint_windows.get(fid, [])

    def in_maintenance(ts):
        for start, end in windows:
            if start <= ts < end:
                return True
        return False

    total = 0.0
    for utc_ts, val, temp in parsed:
        if val is None:
            continue
        if not (DAY_START_UTC <= utc_ts < DAY_END_UTC):
            continue
        if in_spike_window(utc_ts):
            continue
        if in_maintenance(utc_ts):
            continue

        true_value = val - offset
        if true_value < 0:
            continue

        if reading_type == "power":
            energy_kwh = true_value * (5.0 / 60.0) if False else None
        else:
            energy_kwh = None

        total += true_value  # placeholder, replaced below

    return total


def compute_interval_hours(parsed_timestamps):
    diffs = []
    for i in range(1, len(parsed_timestamps)):
        d = (parsed_timestamps[i] - parsed_timestamps[i - 1]).total_seconds() / 60.0
        if d > 0:
            diffs.append(d)
    if not diffs:
        return None
    diffs.sort()
    mid = diffs[len(diffs) // 2]
    return mid / 60.0


def answer():
    farm_tz_by_name = load_farm_timezones()
    name_to_id = load_registry()
    calib = load_calibration()

    id_to_tz = {}
    for name, fid in name_to_id.items():
        id_to_tz[fid] = farm_tz_by_name[name]

    maint_windows = maintenance_windows_utc(id_to_tz)

    result = {}

